func (s *Store) htmxSearch(w http.ResponseWriter, r *http.Request) {
	_ = r.ParseForm()
	origin := resolveAirportCode(r.FormValue("origin"))
	dest := resolveAirportCode(r.FormValue("destination"))
	departure := r.FormValue("departure_date")
	ret := r.FormValue("return_date")
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	if origin == "" || dest == "" {
		_, _ = w.Write([]byte(`<p class="muted">Enter an origin and destination to search live flights.</p>`))
		return
	}
	live, err := duffelSearch(origin, dest, departure, ret, 2)
	if err != nil || len(live) == 0 {
		_, _ = w.Write([]byte(`<p class="muted">No live flights found for ` + origin + ` → ` + dest + `. (Set DUFFEL_API_KEY for live offers.)</p>`))
		return
	}
	var sb strings.Builder
	for i := range live {
		live[i].Source = "duffel"
		s.mu.Lock()
		s.live[live[i].ID] = live[i]
		s.mu.Unlock()
		s.renderFlightCard(&sb, live[i])
	}
	_, _ = w.Write([]byte(sb.String()))
}

func (s *Store) renderFlightCard(sb *strings.Builder, f Flight) {
	logo := `<div class="card-img">✈</div>`
	if f.LogoURL != "" {
		logo = `<div class="card-img" style="background-image:url('` + f.LogoURL + `');background-size:contain;background-repeat:no-repeat;background-position:center;"></div>`
	}
	dist := ""
	if d, dur := flightDistance(f.Origin, f.Destination); d > 0 {
		dist = " · " + strconv.FormatFloat(d, 'f', 0, 64) + " km · " + dur
	}
	sb.WriteString(`<div class="card">`)
	sb.WriteString(logo)
	sb.WriteString(`<div class="card-body">`)
	sb.WriteString(`<div class="card-top"><strong>` + f.Airline + `</strong> <span class="muted">` + f.FlightNumber + `</span><span class="badge">live · Duffel</span><span class="price">$` + strconv.Itoa(f.Price) + `</span></div>`)
	sb.WriteString(`<div class="row">` + f.Origin + ` → ` + f.Destination + `</div>`)
	sb.WriteString(`<div class="row muted">` + f.Departure + ` · ` + strconv.Itoa(f.Stops) + ` stop(s)` + dist + `</div>`)
	sb.WriteString(`<button class="btn" hx-post="/book" hx-vals='{"flight_id":"` + f.ID + `"}' hx-target="#bookings" hx-swap="innerHTML">Book</button>`)
	sb.WriteString(`</div></div>`)
}

func (s *Store) htmxBook(w http.ResponseWriter, r *http.Request) {
	_ = r.ParseForm()
	id := r.FormValue("flight_id")
	f := s.findFlight(id)
	if f == nil {
		_, _ = w.Write([]byte(`<p class="muted">Flight not found.</p>`))
		return
	}
	s.mu.Lock()
	bid := s.newID("FL")
	b := Booking{BookingID: bid, TripID: "TRIP-001", Status: "CONFIRMED", Flight: *f,
		Travelers: 2, Price: f.Price, Currency: f.Currency, CreatedAt: time.Now().UTC().Format(time.RFC3339)}
	s.bookings[bid] = b
	s.mu.Unlock()
	s.renderBookings(w)
}

func (s *Store) htmxCancel(w http.ResponseWriter, r *http.Request) {
	_ = r.ParseForm()
	s.mu.Lock()
	if b, ok := s.bookings[r.FormValue("booking_id")]; ok {
		b.Status = "CANCELLED"
		s.bookings[b.BookingID] = b
	}
	s.mu.Unlock()
	s.renderBookings(w)
}

func (s *Store) htmxBookings(w http.ResponseWriter, r *http.Request) { s.renderBookings(w) }

func (s *Store) renderBookings(w http.ResponseWriter) {
	s.mu.Lock()
	bs := make([]Booking, 0, len(s.bookings))
	for _, b := range s.bookings {
		bs = append(bs, b)
	}
	s.mu.Unlock()
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	if len(bs) == 0 {
		_, _ = w.Write([]byte(`<p class="muted">No bookings yet.</p>`))
		return
	}
	var sb strings.Builder
	for _, b := range bs {
		sb.WriteString(`<div class="card">`)
		sb.WriteString(`<div class="card-top"><strong>` + b.Flight.Airline + `</strong> <span class="badge">` + b.Status + `</span><span class="price">$` + strconv.Itoa(b.Price) + `</span></div>`)
		sb.WriteString(`<div class="row muted">` + b.BookingID + ` · ` + b.Flight.Origin + ` → ` + b.Flight.Destination + `</div>`)
		if b.Status == "CONFIRMED" {
			sb.WriteString(`<button class="btn btn-ghost" hx-post="/cancel" hx-vals='{"booking_id":"` + b.BookingID + `"}' hx-target="#bookings" hx-swap="innerHTML">Cancel</button>`)
		}
		sb.WriteString(`</div>`)
	}
	_, _ = w.Write([]byte(sb.String()))
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

func withJSON(h func(w http.ResponseWriter, r *http.Request)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		h(w, r)
	}
}

func writeJSON(w http.ResponseWriter, v any) {
	_ = json.NewEncoder(w).Encode(v)
}

func writeErr(w http.ResponseWriter, code int, msg string) {
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(map[string]string{"error": msg})
}

func getenv(k, def string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return def
}

func splitOrigins(s string) []string {
	parts := strings.Split(s, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}
package main

// Duffel flight-offers client (test mode).
//
// FlyNow's search returns deterministic mock flights by default. When
// DUFFEL_API_KEY is set, search also pulls live NDC offers from Duffel (test
// mode) and maps them to the same Flight shape. Booking of a Duffel offer is
// still mocked (no real order creation without passenger identity).
//
// Verified against the real API (2026-08): Duffel now requires
// `Duffel-Version: v2` and JSON bodies nested under a `data` key; offers come
// back synchronously on the offer_requests response under `data.offers`.

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

const duffelBase = "https://api.duffel.com"
const duffelVersion = "v2"

var duffelHTTP = &http.Client{Timeout: 30 * time.Second}

type duffelOffer struct {
	ID            string `json:"id"`
	TotalAmount   string `json:"total_amount"`
	TotalCurrency string `json:"total_currency"`
	Owner         struct {
		Name          string `json:"name"`
		LogoSymbolURL string `json:"logo_symbol_url"`
	} `json:"owner"`
	Slices []struct {
		Origin struct {
			IataCode string `json:"iata_code"`
		} `json:"origin"`
		Destination struct {
			IataCode string `json:"iata_code"`
		} `json:"destination"`
		Segments []struct {
			DepartingAt                  string `json:"departing_at"`
			ArrivingAt                   string `json:"arriving_at"`
			OperatingCarrierFlightNumber string `json:"operating_carrier_flight_number"`
		} `json:"segments"`
	} `json:"slices"`
}

func duffelSearch(origin, dest, depart, ret string, travelers int) ([]Flight, error) {
	if os.Getenv("DUFFEL_API_KEY") == "" {
		return nil, nil // not configured -> fall back to mock
	}
	if travelers <= 0 {
		travelers = 2
	}

	slices := []map[string]any{
		{"origin": strings.ToUpper(origin), "destination": strings.ToUpper(dest), "departure_date": depart},
	}
	if ret != "" {
		slices = append(slices, map[string]any{"origin": strings.ToUpper(dest), "destination": strings.ToUpper(origin), "departure_date": ret})
	}
	passengers := make([]map[string]any, travelers)
	for i := range passengers {
		passengers[i] = map[string]any{"type": "adult"}
	}

	var resp struct {
		Data struct {
			Offers []duffelOffer `json:"offers"`
		} `json:"data"`
	}
	if err := duffelCall("POST", "/air/offer_requests", map[string]any{
		"data": map[string]any{"slices": slices, "passengers": passengers, "cabin_class": "economy"},
	}, &resp); err != nil {
		return nil, err
	}

	out := make([]Flight, 0, len(resp.Data.Offers))
	for _, o := range resp.Data.Offers {
		if len(o.Slices) == 0 {
			continue
		}
		s0 := o.Slices[0]
		price, _ := strconv.ParseFloat(o.TotalAmount, 64)
		f := Flight{
			ID:          o.ID,
			Airline:     o.Owner.Name,
			Origin:      s0.Origin.IataCode,
			Destination: s0.Destination.IataCode,
			Stops:       max(0, len(s0.Segments)-1),
			Price:       int(price + 0.5),
			Currency:    o.TotalCurrency,
			Cabin:       "Economy",
			LogoURL:     o.Owner.LogoSymbolURL,
		}
		if len(s0.Segments) > 0 {
			f.FlightNumber = s0.Segments[0].OperatingCarrierFlightNumber
			f.Departure = s0.Segments[0].DepartingAt
			f.Arrival = s0.Segments[0].ArrivingAt
		}
		if len(o.Slices) > 1 && len(o.Slices[1].Segments) > 0 {
			f.ReturnDeparture = o.Slices[1].Segments[0].DepartingAt
			f.ReturnArrival = o.Slices[1].Segments[0].ArrivingAt
		}
		if d, dur := flightDistance(f.Origin, f.Destination); d > 0 {
			f.DistanceKm = d
			f.Duration = dur
		}
		out = append(out, f)
	}

	// Cheapest first; cap so the response stays readable for the agent/UI.
	sort.Slice(out, func(i, j int) bool { return out[i].Price < out[j].Price })
	if len(out) > 12 {
		out = out[:12]
	}
	return out, nil
}

func duffelCall(method, path string, body any, out any) error {
	var rdr io.Reader
	if body != nil {
		b, _ := json.Marshal(body)
		rdr = bytes.NewReader(b)
	}
	req, err := http.NewRequest(method, duffelBase+path, rdr)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+os.Getenv("DUFFEL_API_KEY"))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Duffel-Version", duffelVersion)
	resp, err := duffelHTTP.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 300 {
		b, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return fmt.Errorf("duffel %s: %s", path, strings.TrimSpace(string(b)))
	}
	if out == nil {
		return nil
	}
	return json.NewDecoder(resp.Body).Decode(out)
}
