<script>
function attachAirportAutocomplete(inputId, listId) {
  const input = document.getElementById(inputId);
  const list = document.getElementById(listId);
  let t = null;
  input.addEventListener('input', () => {
    clearTimeout(t);
    const q = input.value.trim();
    if (q.length < 1) { list.style.display = 'none'; return; }
    t = setTimeout(async () => {
      try {
        const r = await fetch('/api/airports?q=' + encodeURIComponent(q));
        const d = await r.json();
        list.innerHTML = '';
        for (const a of (d.airports || [])) {
          const el = document.createElement('div');
          el.className = 'ac-item';
          el.innerHTML = `<span>${a.code} — ${a.city}, ${a.country}</span>`;
          el.onmousedown = (e) => { e.preventDefault(); input.value = a.code; list.style.display = 'none'; };
          list.appendChild(el);
        }
        list.style.display = (d.airports && d.airports.length) ? 'block' : 'none';
      } catch (e) { list.style.display = 'none'; }
    }, 200);
  });
  document.addEventListener('click', (e) => { if (!e.target.closest('.ac')) list.style.display = 'none'; });
}
