func TestFlightSearchToBooking(t *testing.T) {
	t.Setenv("DUFFEL_API_KEY", "")
	s := newStore()

	// Invoke the same JSON handlers used by WebMCP, without opening a socket.
	call := func(handler http.HandlerFunc, path string, input, output any) {
		t.Helper()
		body, err := json.Marshal(input)
		if err != nil {
			t.Fatal(err)
		}
		req := httptest.NewRequest(http.MethodPost, path, bytes.NewReader(body))
		req.Header.Set("Content-Type", "application/json")
		rec := httptest.NewRecorder()
		withJSON(handler).ServeHTTP(rec, req)
		if rec.Code != http.StatusOK {
			if path == "/api/book_flight" {
				t.Logf("%s: status %d: %s", path, rec.Code, rec.Body.String())
				t.Fatal("booking lost the selected flight")
			}
			t.Fatalf("%s: status %d: %s", path, rec.Code, rec.Body.String())
		}
		if err := json.Unmarshal(rec.Body.Bytes(), output); err != nil {
			t.Fatalf("%s: decode response: %v", path, err)
		}
	}

	var search struct {
		Flights []json.RawMessage `json:"flights"`
	}
	// An unfiltered search avoids depending on mock routes, dates, or prices.
	call(s.searchFlights, "/api/search_flights", map[string]any{"travelers": 2}, &search)
	if len(search.Flights) == 0 {
		t.Fatal("search returned no mock flights")
	}
	// Prefer a result other than the first to catch booking a default flight.
	selectedJSON := search.Flights[len(search.Flights)-1]
	// Pin the existing caller's wire contract independently of Flight's tags.
	// A coordinated API migration must update callers as well as the server.
	var wire struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(selectedJSON, &wire); err != nil {
		t.Fatal(err)
	}
	if wire.ID == "" {
		t.Log("search result omitted the existing caller's id field")
		t.Fatal("booking lost the selected flight")
	}
	var selected Flight
	if err := json.Unmarshal(selectedJSON, &selected); err != nil {
		t.Fatal(err)
	}
	selected.ID = wire.ID
	var booked struct {
		Booking Booking `json:"booking"`
	}
	call(s.bookFlight, "/api/book_flight", map[string]any{
		"flight_id": wire.ID, "travelers": 2,
	}, &booked)
	if booked.Booking.BookingID == "" || booked.Booking.Status != "CONFIRMED" {
		t.Fatalf("expected a confirmed booking, got %+v", booked.Booking)
	}

	assertFlight := func(actual Flight) {
		t.Helper()
		// Search adds these derived display estimates; booking stores the
		// inventory flight. Compare every other field, including its ID.
		expected := selected
		expected.DistanceKm, expected.Duration = 0, ""
		actual.DistanceKm, actual.Duration = 0, ""
		if actual != expected {
			t.Fatal("booking lost the selected flight")
		}
	}
	assertFlight(booked.Booking.Flight)
	saved, ok := s.bookings[booked.Booking.BookingID]
	if !ok {
		t.Fatal("booking was not saved")
	}
	assertFlight(saved.Flight)
}
# flynow

A standalone, self-hostable **WebMCP travel provider** (flight search & booking).

flynow is an independent web application with two modes that share one state:

- **Human mode** — a plain HTMX UI (search and book).
- **Agent mode** — the same capabilities exposed to AI agents through the WebMCP `document.modelContext` API.

It is consumed by [Concierge](../concierge), the WebMCP host, which embeds flynow as a cross-origin iframe, discovers its tools with `getTools({ fromOrigins })`, and executes them with `executeTool()`.

## Run

```bash
go run .
# -> http://localhost:8081
```

## WebMCP tools

```text
search_flights
get_flight_details
check_flight_availability
hold_flight
book_flight
cancel_flight
```

## Data sources

- **Duffel** (live flight offers, test mode) — when `DUFFEL_API_KEY` is set.
- Real airport database + great-circle distance/duration.

## Configuration

| Var | Default | Purpose |
|---|---|---|
| `PORT` | `8081` | Listen port |
| `EXPOSED_ORIGINS` | `http://localhost:8080` | Origins allowed to see/execute the tools |
| `DUFFEL_API_KEY` | — | Optional live flight offers |
| `ORIGIN_TRIAL_TOKEN` | — | Optional WebMCP origin-trial token |

## Golden demo data

Air France AF-104, Lagos → Paris, $842.

See the [Concierge README](../concierge/README.md) for the full architecture and the golden trip.
