   {"id":"live-return-stop","total_amount":"200.00","total_currency":"USD","slices":[{"segments":[{"departing_at":"out","arriving_at":"out-arrival"}]},{"segments":[{"departing_at":"return","arriving_at":"connection"},{"departing_at":"connection","arriving_at":"final"}]}]},
   {"id":"invalid","slices":[]}
  ]}}`
  return &http.Response{StatusCode:200, Body:io.NopCloser(strings.NewReader(body)), Header:make(http.Header)}, nil
 })}
}

func TestSearchDuffelCombinedResults(t *testing.T) {
 stubSearchDuffel(t)
 s := newStore()
 results := searchJSON(t, s, `{"origin":"LOS","destination":"CDG","travelers":3}`, http.StatusOK)
 want := []string{"FL-001","FL-002","FL-003","FL-004","FL-005","live-return-stop","live-direct"}
 if !reflect.DeepEqual(searchIDs(results), want) { t.Fatalf("default combined order = %v", searchIDs(results)) }
 results = searchJSON(t, s, `{"origin":"LOS","destination":"CDG","travelers":3,"nonstop":true,"sort_by_price":"desc"}`, http.StatusOK)
 if !reflect.DeepEqual(searchIDs(results), []string{"live-direct"}) { t.Fatalf("nonstop = %v", results) }
 f := results[0]
 if f["price_display"] != "USD 342.00" || f["source"] != "duffel" || f["price"] != float64(342) { t.Fatalf("bad mapped flight: %v", f) }
 if s.live["live-direct"].ID != "live-direct" { t.Fatal("live flight was not cached for subsequent tools") }
 results = searchJSON(t, s, `{"origin":"LOS","destination":"CDG","travelers":3,"sort_by_price":"asc"}`, http.StatusOK)
 if !reflect.DeepEqual(searchIDs(results), []string{"live-return-stop","live-direct","FL-005","FL-001","FL-002","FL-003","FL-004"}) { t.Fatalf("combined sort = %v", searchIDs(results)) }
 if s.live["live-return-stop"].Stops != 1 || s.live["live-return-stop"].ReturnArrival != "final" { t.Fatal("return connection mapped incorrectly") }
}

func TestSearchHumanMockAndOptions(t *testing.T) {
 t.Setenv("DUFFEL_API_KEY", "")
 s := newStore()
 call := func(values url.Values) *httptest.ResponseRecorder {
  t.Helper()
  req := httptest.NewRequest(http.MethodPost,"/search",strings.NewReader(values.Encode()))
  req.Header.Set("Content-Type","application/x-www-form-urlencoded")
  rec := httptest.NewRecorder()
  s.htmxSearch(rec,req)
  return rec
 }
 values := url.Values{"origin":{"LOS"},"destination":{"CDG"},"sort_by_price":{"asc"}}
 rec := call(values)
 body := rec.Body.String()
 if rec.Code != 200 || !strings.Contains(body,"USD 798.00") || !strings.Contains(body,"mock") || strings.Contains(body,"live · Duffel") { t.Fatalf("mock UI: %s", body) }
 if strings.Index(body,"Turkish Airlines") > strings.Index(body,"Air France") { t.Fatal("human sort not applied") }
 values.Set("sort_by_price","desc")
 body = call(values).Body.String()
 if strings.Index(body,"British Airways") > strings.Index(body,"Air France") { t.Fatal("descending human sort not applied") }
 values.Set("nonstop","true")
 if body = call(values).Body.String(); !strings.Contains(body,"No flights found") || strings.Contains(body,`class="card"`) { t.Fatalf("human nonstop: %s",body) }
 values.Set("sort_by_price","invalid")
 if call(values).Code != 400 { t.Fatal("human invalid sort should return 400") }
}

func TestSearchHumanDuffelTravelerCount(t *testing.T) {
 stubSearchDuffel(t)
 req := httptest.NewRequest(http.MethodPost,"/search",strings.NewReader("origin=LOS&destination=CDG&travelers=3&nonstop=true&sort_by_price=asc"))
 req.Header.Set("Content-Type","application/x-www-form-urlencoded")
 rec := httptest.NewRecorder()
 newStore().htmxSearch(rec,req)
 body := rec.Body.String()
 if !strings.Contains(body,"USD 342.00") || !strings.Contains(body,"live · Duffel") || strings.Contains(body,"Air France") { t.Fatalf("live filtered UI: %s",body) }
}

func TestSearchMapping(t *testing.T) {
 for _, currency := range []string{"USD","EUR","NGN"} {
  if got := mapSearchResult(Flight{Currency:currency,Price:342}).PriceDisplay; got != currency+" 342.00" { t.Fatalf("display = %q",got) }
 }
 for _, raw := range []string{`{}`,`{"slices":[{"segments":[]}]}`} {
  var offer duffelOffer
  if err := json.Unmarshal([]byte(raw),&offer); err != nil { t.Fatal(err) }
  if _,ok := mapDuffelOffer(offer); ok { t.Fatal("invalid offer accepted as a nonstop flight") }
 }
 rec := httptest.NewRecorder()
 servePage(rec, []string{"http://localhost:8080"})
 if rec.Code != 200 { t.Fatal("page did not render") }
 for _, expected := range []string{`name="nonstop"`, `name="sort_by_price"`, `nonstop: { type: 'boolean'`, `enum: ['asc', 'desc']`, `Returns flight_id`} {
  if !strings.Contains(rec.Body.String(),expected) { t.Fatalf("page missing %q",expected) }
 }
}
